def solve(grid):
    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    from collections import deque
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    # Initialize queue with all boundary cells that are 0
    for r in range(rows):
        if grid[r][0] == 0 and not visited[r][0]:
            visited[r][0] = True
            queue.append((r, 0))
        if grid[r][cols-1] == 0 and not visited[r][cols-1]:
            visited[r][cols-1] = True
            queue.append((r, cols-1))

    for c in range(cols):
        if grid[0][c] == 0 and not visited[0][c]:
            visited[0][c] = True
            queue.append((0, c))
        if grid[rows-1][c] == 0 and not visited[rows-1][c]:
            visited[rows-1][c] = True
            queue.append((rows-1, c))

    # BFS to mark all 0s connected to boundary
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == 0:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Create result: enclosed 0s become 4, others stay same
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                result[r][c] = 4

    return result

